    manifest.canonicalTask,
    manifest.skill,
    ...manifest.materials,
    manifest.referenceNotes,
    ...manifest.dependencies,
    ...manifest.compilerPrivate,
    ...manifest.runtimeExecutables,
    manifest.consumer,
    manifest.bService,
  ]) {
